import { mapVscodeThemeToDryl } from "./vscode-theme-map.mjs";

const SCSS_VAR_ORDER = [
  "--background-primary-base",
  "--background-secondary-base",
  "--background-tertiary-base",
  "--list-hover-background-base",
  "--border-primary-base",
  "--border-secondary-base",
  "--text-primary",
  "--text-secondary",
  "--text-muted",
  "--danger-primary",
  "--highlight-primary",
  "--accent-primary",
  "--accent-secondary",
  "--warning-primary",
  "--success-primary",
  "--info-primary",
  "--accent-border",
];

function scssVars(theme, extraLines = []) {
  const mapped = mapVscodeThemeToDryl(theme);
  const lines = [`  color-scheme: ${theme.type === "dark" ? "dark" : "light"};`];
  for (const name of SCSS_VAR_ORDER) {
    const value = mapped[name];
    if (value) lines.push(`  ${name}: ${value};`);
  }
  if (mapped["--accent-primary"]) {
    lines.push("  --bird-crow: var(--accent-primary);");
  }
  if (mapped["--accent-secondary"]) {
    lines.push("  --bird-magpie: var(--accent-secondary);");
  }
  if (mapped["--warning-primary"]) {
    lines.push("  --bird-pigeon: var(--warning-primary);");
  }
  for (const line of extraLines) {
    lines.push(line);
  }
  return lines.join("\n");
}

/** CSS custom properties for one VS Code theme (optional extra lines per app). */
export function cssVarsForTheme(theme, extraLines = []) {
  return scssVars(theme, extraLines);
}

export function systemPrefBlock(slot, theme, extraLines = []) {
  const media =
    slot === "dark"
      ? "@media (prefers-color-scheme: dark)"
      : "@media (prefers-color-scheme: light)";
  return `${media} {\n  :root:not([data-theme]) {\n${scssVars(theme, extraLines)}\n  }\n}`;
}

export function blockForSlot(slot, theme, extraLines = []) {
  return `:root[data-theme="${slot}"] {\n${scssVars(theme, extraLines)}\n}`;
}

function dataThemeBlock(slot, theme) {
  return blockForSlot(slot, theme);
}

export function renderStandardThemeScss({ light, dark, lightSource, darkSource }) {
  return [
    "// Generated by @dryl/ui/theme — do not edit manually",
    `// Source: themes/vscode-imports/${lightSource}, themes/vscode-imports/${darkSource}`,
    "",
    systemPrefBlock("dark", dark),
    "",
    systemPrefBlock("light", light),
    "",
    dataThemeBlock("dark", dark),
    "",
    dataThemeBlock("light", light),
    "",
  ].join("\n");
}

export function renderThemeStubScss() {
  return "// @dryl/ui vscode-theme stub — no themes/vscode-imports/*.json imported yet\n";
}

export function pickThemePair(entries) {
  const light = entries.find((e) => /light/i.test(e.name)) ?? null;
  const dark =
    entries.find((e) => /dark/i.test(e.name)) ??
    entries.find((e) => e !== light) ??
    null;
  return { light, dark };
}
